async function createTask(task: TaskDefinition): Promise<{ id: number; url: string } | null> {
  // JSON-Patch: one 'add' op per field, keyed by ADO reference name (not the UI label).
  const patchDocument = [
    { op: 'add', path: '/fields/System.Title', value: task.title },
    // Description/AcceptanceCriteria render as HTML in ADO -> convert newlines to <br> or they collapse to one line.
    { op: 'add', path: '/fields/System.Description', value: task.description.replace(/\n/g, '<br>') },
    { op: 'add', path: '/fields/Microsoft.VSTS.Common.AcceptanceCriteria', value: task.acceptanceCriteria.replace(/\n/g, '<br>') },
    // Priority is numeric in ADO; map the label to 1-4, default 2 for anything unmapped.
    { op: 'add', path: '/fields/Microsoft.VSTS.Common.Priority', value: priorityMap[task.priority] || 2 },
    { op: 'add', path: '/fields/System.Tags', value: task.tags },
  ];

  if (task.parentUS.length > 0) {
    patchDocument.push({
      op: 'add',
      path: '/relations/-', // '-' appends to the relations array
      value: {
        // Hierarchy-REVERSE = child -> parent (nests THIS task under the story); Forward would invert it.
        rel: 'System.LinkTypes.Hierarchy-Reverse',
        url: `https://dev.azure.com/my-org/_apis/wit/workItems/${task.parentUS[0]}`,
        attributes: { comment: `Child of US ${task.parentUS[0]}` },
      },
    });
  }

  // $Task: the literal '$' prefix on the type is required by the create endpoint;
  // content type MUST be application/json-patch+json, not plain application/json.
  const response = await fetch(`${BASE_URL}/wit/workitems/$Task?api-version=7.0`, {
    method: 'POST',
    headers: { Authorization: authHeader, 'Content-Type': 'application/json-patch+json' },
    body: JSON.stringify(patchDocument),
  });
  const result = await response.json();
  return { id: result.id, url: result._links?.html?.href };
}

async function linkToParent(taskId: number, parentId: string): Promise<boolean> {
  // Same single 'add' op on /relations/- as creation, just applied afterward for parents 2..N.
  const patchDocument = [{
    op: 'add',
    path: '/relations/-',
    value: {
      rel: 'System.LinkTypes.Hierarchy-Reverse', // child -> parent, same as the inline first link
      url: `https://dev.azure.com/my-org/_apis/wit/workItems/${parentId}`,
      attributes: { comment: `Child of US ${parentId}` },
    },
  }];

  // PATCH the EXISTING task (not $Task create); json-patch content type still required.
  const response = await fetch(`${BASE_URL}/wit/workitems/${taskId}?api-version=7.0`, {
    method: 'PATCH',
    headers: { Authorization: authHeader, 'Content-Type': 'application/json-patch+json' },
    body: JSON.stringify(patchDocument),
  });
  return response.ok; // return the boolean, don't throw - lets the caller flag one bad link and continue
}

for (const task of tasks) {
  const created = await createTask(task);
  if (created) {
    // parentUS[0] was linked inline during creation, so seed 'linked' with it and start the loop at 1.
    const linked: string[] = [task.parentUS[0]];
    for (let i = 1; i < task.parentUS.length; i++) {
      const ok = await linkToParent(created.id, task.parentUS[i]);
      // Only record a parent as linked if its PATCH actually succeeded -> partial links show honestly.
      if (ok) linked.push(task.parentUS[i]);
    }
    results.push({ task, adoId: created.id, url: created.url, linked });
  } else {
    // Failed create -> null-ID row, so one bad task doesn't crash the whole batch.
    results.push({ task, adoId: null, url: null, linked: [] });
  }
}

// Print summary table - status is derived purely from whether an adoId came back.
console.log('| Task | ADO ID | Parent US | Status |');
for (const r of results) {
  const status = r.adoId ? 'Created' : 'Failed';
  // N/A / '-' stand in for a missing ID and an empty parent list respectively.
  console.log(`| ${r.task.id} | ${r.adoId || 'N/A'} | ${r.linked.join(', ') || '-'} | ${status} |`);
}

